def forward(self, taskInfo):
    import json

    # Parameters
    beam_width = 3
    max_depth = 3
    diversity_lambda = 0.3  # reduced to avoid overly penalizing
    gen_width = 3

    # Agents
    expander = LLMAgentBase(["candidates"], "Expander", 
        role="You generate multiple diverse next steps. Output JSON with key 'candidates' containing a list of strings.", temperature=0.7)
    evaluator = LLMAgentBase(["score"], "Evaluator",
        role="You evaluate a reasoning path and output a JSON object with key 'score' (a number between 0 and 1).", temperature=0.2)
    diversity_judge = LLMAgentBase(["novelty"], "DiversityJudge",
        role="You compare two reasoning paths and output a JSON object with key 'novelty' (0-1) for the second path relative to the first.", temperature=0.2)
    final_agent = LLMAgentBase(["thinking", "answer"], "FinalAnswer",
        role="You derive the final answer from the best reasoning path.", temperature=0.3)

    # Initialize beam with an empty path: a list of Info objects for thoughts
    beam_thoughts = [[]]  # each element is a list of Info objects

    for depth in range(max_depth):
        all_candidates = []  # each element: (score, thought_infos_list)

        for thoughts in beam_thoughts:
            # Generate next steps
            expand_input = [taskInfo] + thoughts
            expand_prompt = f"Given the reasoning so far, generate {gen_width} diverse next steps. Output JSON with key 'candidates' as a list of strings."
            # Get response; expander returns a list of Info with one Info for 'candidates'
            candidates_info_list = expander(expand_input, expand_prompt)
            # The first Info contains the output for 'candidates'
            candidates_info = candidates_info_list[0]
            content = candidates_info.content
            # Try to parse JSON from the content string
            if isinstance(content, str):
                try:
                    data = json.loads(content)
                except json.JSONDecodeError:
                    data = {}
            elif isinstance(content, dict):
                data = content
            else:
                data = {}
            candidates = data.get("candidates", [])
            if not isinstance(candidates, list):
                candidates = [candidates]

            for step in candidates:
                if not isinstance(step, str):
                    step = str(step)
                # Create an Info object for this thought step
                new_thought_info = Info("thought", "Expander", step, depth)
                new_thoughts = thoughts + [new_thought_info]
                # Evaluate the new path
                eval_input = [taskInfo] + new_thoughts
                eval_prompt = "Evaluate the reasoning path and output a JSON object with key 'score' (a number between 0 and 1)."
                score_info_list = evaluator(eval_input, eval_prompt)
                score_info = score_info_list[0]
                score_content = score_info.content
                if isinstance(score_content, str):
                    try:
                        score_data = json.loads(score_content)
                    except json.JSONDecodeError:
                        score_data = {}
                else:
                    score_data = score_content
                try:
                    score = float(score_data.get("score", 0.5))
                except:
                    score = 0.5
                all_candidates.append((score, new_thoughts))

        if not all_candidates:
            break

        # Sort by score descending
        all_candidates.sort(key=lambda x: x[0], reverse=True)

        # Greedy selection with diversity penalty
        selected = [all_candidates[0]]  # keep highest score path
        remaining = all_candidates[1:]

        while len(selected) < beam_width and remaining:
            best_adj_score = -float("inf")
            best_candidate_idx = None
            for idx, (score, thoughts) in enumerate(remaining):
                # Compute max diversity penalty against all selected paths
                max_penalty = 0.0
                for selected_score, selected_thoughts in selected:
                    # Build the path strings for comparison (just the thought contents)
                    # We'll use the full thought list to create a summary
                    sel_path_str = " ".join([t.content for t in selected_thoughts])
                    cand_path_str = " ".join([t.content for t in thoughts])
                    # Create input for diversity judge
                    judge_input = [
                        taskInfo,
                        Info("selected_path", "SelectedPath", sel_path_str, 0),
                        Info("candidate_path", "CandidatePath", cand_path_str, 0)
                    ]
                    judge_prompt = "Output a JSON object with key 'novelty' (0-1) indicating how novel the candidate path is compared to the selected path. 1 means completely different."
                    novelty_info_list = diversity_judge(judge_input, judge_prompt)
                    novelty_info = novelty_info_list[0]
                    nov_content = novelty_info.content
                    if isinstance(nov_content, str):
                        try:
                            nov_data = json.loads(nov_content)
                        except json.JSONDecodeError:
                            nov_data = {}
                    else:
                        nov_data = nov_content
                    try:
                        novelty = float(nov_data.get("novelty", 0.5))
                    except:
                        novelty = 0.5
                    penalty = 1.0 - novelty
                    if penalty > max_penalty:
                        max_penalty = penalty
                adj_score = score - diversity_lambda * max_penalty
                if adj_score > best_adj_score:
                    best_adj_score = adj_score
                    best_candidate_idx = idx
            if best_candidate_idx is not None:
                selected.append(remaining[best_candidate_idx])
                del remaining[best_candidate_idx]
            else:
                break

        # Update beam_thoughts with the selected thought lists
        beam_thoughts = [thoughts for (score, thoughts) in selected]

    # After all depths, pick best path (highest score) from final beam
    if beam_thoughts:
        # We need scores to compare; we stored scores in the selected list, but we only kept thoughts.
        # We should re-evaluate the final paths to get the best one, or we can keep scores during selection.
        # To keep it simple, we re-evaluate each final path using the evaluator.
        best_score = -1.0
        best_thoughts = None
        for thoughts in beam_thoughts:
            eval_input = [taskInfo] + thoughts
            eval_prompt = "Evaluate the reasoning path and output a JSON object with key 'score' (0-1)."
            score_info_list = evaluator(eval_input, eval_prompt)
            score_info = score_info_list[0]
            score_content = score_info.content
            if isinstance(score_content, str):
                try:
                    score_data = json.loads(score_content)
                except:
                    score_data = {}
            else:
                score_data = score_content
            try:
                score = float(score_data.get("score", 0.0))
            except:
                score = 0.0
            if score > best_score:
                best_score = score
                best_thoughts = thoughts
        if best_thoughts is None:
            best_thoughts = []
    else:
        best_thoughts = []

    # Synthesize final answer
    final_input = [taskInfo] + best_thoughts
    final_prompt = "Based on the reasoning steps provided, derive the final answer in \\boxed{...}."
    _, answer = final_agent(final_input, final_prompt)
    return answer

def forward(self, taskInfo):
    import re
    from collections import Counter

    # Parameters
    NUM_STRATEGIES = 4
    MAX_ROUNDS = 3

    # Define strategy agents (diverse reasoning approaches)
    # Use higher temperature for initial generation to encourage diversity
    strategy_agents = [
        LLMAgentBase(['thinking', 'answer'], 'Algebrist',
                     role="You are a math problem solver specializing in algebraic manipulation. Solve the problem step-by-step using equations and algebraic techniques. Output JSON with keys 'thinking' and 'answer' in \boxed{...}.",
                     temperature=0.7),
        LLMAgentBase(['thinking', 'answer'], 'Caseworker',
                     role="You are a math problem solver specializing in casework and enumeration. Solve the problem by breaking it into cases and counting or analyzing each systematically. Output JSON with keys 'thinking' and 'answer' in \boxed{...}.",
                     temperature=0.7),
        LLMAgentBase(['thinking', 'answer'], 'Modularist',
                     role="You are a math problem solver specializing in modular arithmetic and number theory. Solve the problem using properties of divisibility, congruences, and prime factors. Output JSON with keys 'thinking' and 'answer' in \boxed{...}.",
                     temperature=0.7),
        LLMAgentBase(['thinking', 'answer'], 'BruteForcer',
                     role="You are a math problem solver specializing in exhaustive enumeration or example-based reasoning. Solve the problem by trying small cases, looking for patterns, or using a systematic brute-force approach. Output JSON with keys 'thinking' and 'answer' in \boxed{...}.",
                     temperature=0.7)
    ]

    # Critic agent (low temperature for consistency)
    critic = LLMAgentBase(['score', 'feedback'], 'Critic',
                          role='You evaluate a solution (thinking and answer) and provide a score (0-1) and constructive feedback. Output JSON with keys "score" (float) and "feedback" (string).',
                          temperature=0.2)

    # Generate initial solutions
    solutions = []
    for agent in strategy_agents:
        try:
            thinking, answer = agent([taskInfo], 'Solve the math problem step-by-step. Put final answer in \boxed{...}.')
            solutions.append({'thinking': thinking, 'answer': answer, 'score': 0.5, 'feedback': ''})
        except Exception:
            pass

    # If no solutions, use fallback
    if len(solutions) == 0:
        fallback = LLMAgentBase(['thinking', 'answer'], 'FallbackSolver', temperature=0.5)
        _, answer = fallback([taskInfo], 'Solve the math problem step-by-step. Put final answer in \boxed{...}.')
        return answer

    # Iterative refinement rounds
    for round_num in range(MAX_ROUNDS):
        # Evaluate current solutions with critic
        for i, sol in enumerate(solutions):
            solution_text = f"Thinking: {sol['thinking'].content}\nAnswer: {sol['answer'].content}"
            crit_input = [taskInfo, Info('solution', f'Strategy_{i}', solution_text, round_num)]
            crit_instruction = 'Evaluate this solution. Output JSON with "score" (float) and "feedback" (string).'
            try:
                crit_result = critic(crit_input, crit_instruction)
                for info in crit_result:
                    if info.name == 'score':
                        sol['score'] = float(info.content)
                    elif info.name == 'feedback':
                        sol['feedback'] = info.content
            except Exception:
                pass

        # Check early termination: if all answers agree
        def extract_answer(ans_info):
            content = ans_info.content
            match = re.search(r'\\boxed\{(.*?)\}', content)
            if match:
                return match.group(1).strip()
            return content.strip()

        answer_texts = [extract_answer(sol['answer']) for sol in solutions]
        if len(set(answer_texts)) == 1:
            break

        # Revision: each agent revises its solution based on others and critique
        new_solutions = []
        for i, sol in enumerate(solutions):
            own_text = f"Thinking: {sol['thinking'].content}\nAnswer: {sol['answer'].content}"
            other_texts = []
            for j, other in enumerate(solutions):
                if i != j:
                    other_texts.append(f"Solver {j} Thinking: {other['thinking'].content}\nSolver {j} Answer: {other['answer'].content}")
            other_text = '\n'.join(other_texts)
            critique_text = f"Score: {sol.get('score', 0.5):.2f}\nFeedback: {sol.get('feedback', '')}"
            rev_input = [taskInfo,
                         Info('own_solution', 'Self', own_text, round_num),
                         Info('other_solutions', 'Others', other_text, round_num),
                         Info('critique', 'Critic', critique_text, round_num)]
            rev_instruction = 'Revise your solution based on the provided information. Output JSON with keys "thinking" and "answer" in \boxed{...}.'
            try:
                new_thinking, new_answer = strategy_agents[i](rev_input, rev_instruction)
                new_solutions.append({'thinking': new_thinking, 'answer': new_answer, 'score': 0.5, 'feedback': ''})
            except Exception:
                new_solutions.append(sol)  # keep old if revision fails
        solutions = new_solutions

    # Final weighted voting based on latest scores
    def extract_answer_text(ans_info):
        content = ans_info.content
        match = re.search(r'\\boxed\{(.*?)\}', content)
        if match:
            return match.group(1).strip()
        return content.strip()

    total_score = sum(sol.get('score', 0.5) for sol in solutions)
    if total_score <= 0:
        total_score = len(solutions) * 0.5
    weights = [sol.get('score', 0.5) / total_score for sol in solutions]

    answer_weight = {}
    for sol, weight in zip(solutions, weights):
        text = extract_answer_text(sol['answer'])
        answer_weight[text] = answer_weight.get(text, 0.0) + weight

    if answer_weight:
        best_text = max(answer_weight, key=answer_weight.get)
        for sol in solutions:
            if extract_answer_text(sol['answer']) == best_text:
                return sol['answer']

    # Fallback: return first solution's answer
    return solutions[0]['answer']

def forward(self, taskInfo):
    import re
    from collections import Counter

    # Parameters
    NUM_STRATEGIES = 4
    MAX_ROUNDS = 3
    SELF_CONSISTENCY_TEMPS = [0.3, 0.5, 0.7]

    # Helper to extract answer text from Info (only for comparison, not for constructing prompts)
    def extract_answer_text(info):
        content = info.content
        match = re.search(r'\\boxed\{(.*?)\}', content)
        if match:
            return match.group(1).strip()
        return content.strip()

    # Helper to get numeric score from Info
    def get_score_value(sol):
        if sol['score'] is not None:
            try:
                return float(sol['score'].content)
            except (ValueError, TypeError, AttributeError):
                return 0.5
        return 0.5

    # Define strategy agents
    strategy_agents = [
        LLMAgentBase(['thinking', 'answer'], 'Algebrist',
                     role="You are a math problem solver specializing in algebraic manipulation. Solve the problem step-by-step using equations and algebraic techniques. Output JSON with keys 'thinking' and 'answer' in \boxed{...}.",
                     temperature=0.7),
        LLMAgentBase(['thinking', 'answer'], 'Caseworker',
                     role="You are a math problem solver specializing in casework and enumeration. Solve the problem by breaking it into cases and counting or analyzing each systematically. Output JSON with keys 'thinking' and 'answer' in \boxed{...}.",
                     temperature=0.7),
        LLMAgentBase(['thinking', 'answer'], 'Modularist',
                     role="You are a math problem solver specializing in modular arithmetic and number theory. Solve the problem using properties of divisibility, congruences, and prime factors. Output JSON with keys 'thinking' and 'answer' in \boxed{...}.",
                     temperature=0.7),
        LLMAgentBase(['thinking', 'answer'], 'BruteForcer',
                     role="You are a math problem solver specializing in exhaustive enumeration or example-based reasoning. Solve the problem by trying small cases, looking for patterns, or using a systematic brute-force approach. Output JSON with keys 'thinking' and 'answer' in \boxed{...}.",
                     temperature=0.7)
    ]

    # Critic agent
    critic = LLMAgentBase(['score', 'feedback'], 'Critic',
                          role='You evaluate a solution (thinking and answer) and provide a score (0-1) and constructive feedback. Output JSON with keys "score" (float) and "feedback" (string).',
                          temperature=0.2)

    # Generate initial solutions: each solution is a dict of Info objects
    solutions = []
    for agent in strategy_agents:
        try:
            thinking, answer = agent([taskInfo], 'Solve the math problem step-by-step. Put final answer in \boxed{...}.')
            solutions.append({'thinking': thinking, 'answer': answer, 'score': None, 'feedback': None})
        except Exception:
            pass

    if len(solutions) == 0:
        fallback = LLMAgentBase(['thinking', 'answer'], 'FallbackSolver', temperature=0.5)
        _, answer = fallback([taskInfo], 'Solve the math problem step-by-step. Put final answer in \boxed{...}.')
        return answer

    # Iterative refinement rounds
    for round_num in range(MAX_ROUNDS):
        # Evaluate all solutions
        for sol in solutions:
            crit_input = [taskInfo, sol['thinking'], sol['answer']]
            crit_instruction = 'Evaluate the solution. Output JSON with "score" (float) and "feedback" (string).'
            try:
                crit_result = critic(crit_input, crit_instruction)
                for info in crit_result:
                    if info.name == 'score':
                        sol['score'] = info
                    elif info.name == 'feedback':
                        sol['feedback'] = info
            except Exception:
                pass

        # Early termination if all answers agree
        answer_texts = [extract_answer_text(sol['answer']) for sol in solutions if sol['answer'] is not None]
        if len(set(answer_texts)) == 1 and len(answer_texts) > 0:
            break

        # Revision: each agent revises its solution using all available Info objects
        new_solutions = []
        for i, sol in enumerate(solutions):
            # Build input list: task, own thinking, own answer, other thinking/answer pairs, critic score, critic feedback
            rev_input = [taskInfo, sol['thinking'], sol['answer']]
            # Add other agents' solutions as separate Info objects
            for j, other in enumerate(solutions):
                if i != j:
                    rev_input.append(other['thinking'])
                    rev_input.append(other['answer'])
            # Add critic feedback if available, else default
            if sol['score'] is not None:
                rev_input.append(sol['score'])
            if sol['feedback'] is not None:
                rev_input.append(sol['feedback'])
            rev_instruction = 'You are given: the problem, your own solution (thinking and answer), other solutions, and critique (score and feedback). Revise your solution to improve it. Output JSON with keys "thinking" and "answer" in \boxed{...}.'
            try:
                new_thinking, new_answer = strategy_agents[i](rev_input, rev_instruction)
                new_solutions.append({'thinking': new_thinking, 'answer': new_answer, 'score': None, 'feedback': None})
            except Exception:
                # Keep old solution if revision fails
                new_solutions.append(sol)
        solutions = new_solutions

    # After rounds, compute weights based on scores
    scores = [get_score_value(sol) for sol in solutions]
    total_score = sum(scores)
    if total_score <= 0:
        total_score = len(solutions) * 0.5
    weights = [s / total_score for s in scores]

    # Weighted majority vote on answer text
    answer_weight = {}
    for sol, w in zip(solutions, weights):
        text = extract_answer_text(sol['answer'])
        answer_weight[text] = answer_weight.get(text, 0.0) + w
    if not answer_weight:
        return solutions[0]['answer']
    best_text = max(answer_weight, key=answer_weight.get)
    best_sol = None
    for sol in solutions:
        if extract_answer_text(sol['answer']) == best_text:
            best_sol = sol
            break
    if best_sol is None:
        return solutions[0]['answer']

    # Self-consistency on the best solution
    candidate_answers = []
    for temp in SELF_CONSISTENCY_TEMPS:
        syn = LLMAgentBase(['thinking', 'answer'], 'SynthesizerSC_' + str(temp),
                           role='Given the problem and a complete reasoning path, produce the final answer in \\boxed{...}. Output JSON with keys "thinking" and "answer".',
                           temperature=temp)
        try:
            _, ans = syn([taskInfo, best_sol['thinking'], best_sol['answer']], 'Based on the given reasoning path, provide the final answer in \boxed{...}.')
            candidate_answers.append(ans)
        except Exception:
            pass

    if len(candidate_answers) == 0:
        return best_sol['answer']

    # Weighted majority among candidates using the best solution's score as weight
    best_score = get_score_value(best_sol)
    candidate_weight = {}
    for ans in candidate_answers:
        text = extract_answer_text(ans)
        candidate_weight[text] = candidate_weight.get(text, 0.0) + best_score
    best_candidate_text = max(candidate_weight, key=candidate_weight.get)
    for ans in candidate_answers:
        if extract_answer_text(ans) == best_candidate_text:
            return ans
    return best_sol['answer']
